import numpy as np
step = 1 / 8192
x = np.arange(-2, 4, step)
def warp(t):
    t = np.asarray(t)
    outside_distance = np.where(t < 0, t, t - 2)
    return np.where((t >= 0) & (t <= 2), np.sin(np.pi*t)**2, -outside_distance**2 / (1 + outside_distance**2))
def f0(t):
    return np.maximum(1 - 8*np.abs(t - 5/8), 0)
def f1(t):
    return np.where((t >= 0) & (t <= 1), f0(warp(t)), 0)
functions = {'f0_id': f0(x), 'f0_warp': f0(warp(x)), 'f1_id': f1(x), 'f1_warp': f1(warp(x))}
inside = (x >= 0) & (x <= 1)
print('Maximum observed-image difference:', np.max(np.abs(functions['f0_warp'][inside] - functions['f1_id'][inside])))
for name, values in functions.items():
    positive = values > 1e-10
    components = np.count_nonzero(positive & ~np.r_[False, positive[:-1]])
    print(name, 'support components:', components, 'L2 norm:', np.sqrt(np.sum(values**2)*step))
fft_size = 1 << ((2*len(x) - 1).bit_length())
reference_norm = np.linalg.norm(functions['f1_id'])
for source_name in ['f0_id', 'f0_warp']:
    for target_name in ['f1_id', 'f1_warp']:
        source, target = functions[source_name], functions[target_name]
