import math
from collections import defaultdict
step = 1/2048
points = [j*step for j in range(-1024, 5121)]
def warp(t):
    if 0 <= t <= 2:
        return math.sin(math.pi*t)**2
    q = t if t < 0 else t-2
    return -q*q/(1+q*q)
def f0(t):
    return max(1-8*abs(t-5/8), 0)
def f1(t):
    return f0(warp(t)) if 0 <= t <= 1 else 0
functions = {'f0_id': [f0(x) for x in points], 'f0_warp': [f0(warp(x)) for x in points], 'f1_id': [f1(x) for x in points], 'f1_warp': [f1(warp(x)) for x in points]}
print('Maximum observed-image difference:', max(abs(f0(warp(x))-f1(x)) for x in points if 0 <= x <= 1))
sparse, norms = {}, {}
for name, values in functions.items():
    sparse[name] = [(i, v) for i, v in enumerate(values) if v > 1e-12]
    norms[name] = math.sqrt(sum(v*v for v in values))
    components = sum(v > 1e-12 and (i == 0 or values[i-1] <= 1e-12) for i, v in enumerate(values))
    print(name, 'support components:', components, 'L2 norm:', round(norms[name]*math.sqrt(step), 6))
for source_name in ['f0_id', 'f0_warp']:
    for target_name in ['f1_id', 'f1_warp']:
        correlations = defaultdict(float)
        for i, a in sparse[source_name]:
            for j, b in sparse[target_name]:
                correlations[j-i] += a*b
        cosine = max(correlations.values())/(norms[source_name]*norms[target_name])
        distance = norms[target_name]/norms['f1_id']*math.sqrt(max(0, 1-cosine*cosine))
        print(source_name, 'vs', target_name, 'approximate distance minimized over amplitude and translation:', round(distance, 6))
